INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('ariveguru', 'AriveGuru Technology Solutions Pvt. Ltd.', 'Frontend Engineer', '2024-03-14', '2024-07-23', 'Bangalore', 'Developed applications for medical firms, enhancing user health tracking and assessments while learning to handle sensitive personal data securely and comply with industry standards. Built RHIA, an AI assistant for tasks including user registration, appointment scheduling, and task management, deployable across multiple office locations, leveraging AI technologies to streamline office operations and improve productivity. Created a JSON to React Native component converter to improve frontend management and development efficiency. Directly coordinated with clients to translate their requirements into pixel-perfect solutions, consistently meeting deadlines and delivering high-quality, responsive designs and interfaces that gained confidence in frontend skills and knowledge.', 'FULL_TIME', '["bvmrf","rhia"]', '{"from":"green","to":"teal"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('konversi', 'Konversi Pvt. Ltd.', 'Mobile Developer', '2024-10-01', '2025-04-30', 'Remote', 'Developed a Fleet Management App with comprehensive job flow management, job history tracking, and real-time location tracking for job assignments, along with image uploads and technician maintenance workflows. Built a POS App for park operations that handled up to 1000+ transactions per day, integrating thermal printer support, transaction history management, and report data printing capabilities. Created an Attendance Logging App using Expo''s geolocation services and camera-based photo verification to enforce secure clock-in/out functionality, manage leave requests, and track daily work hours for employees.', 'CONTRACT', '["konversi-fleet","konversi-pos","konversi-attendance"]', '{"from":"purple","to":"pink"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('lovepack', 'Lovepack Consumers Pvt. Ltd.', 'Software Engineer', '2024-08-01', '2026-09-01', 'Remote', 'Developed three major applications: EazyDukan, a multilingual retail management platform (mobile & web) featuring subscription tiers, multi-outlet and staff management, a full POS system with real-time inventory tracking, AI-powered menu scanning, promotional material generation, and online ordering with delivery coordination. Built WebRasoi, a restaurant-focused version with enhanced AI-based menu creation from photos and streamlined inventory management. Created Zluper, a thrift fashion marketplace with an Instagram Reels-like feed optimized with HLS video streaming and WebP images, featuring wishlisting, rewards, referrals, wallet cashbacks, creator program, and a comprehensive admin dashboard for managing inventory, orders, and platform operations. All projects utilized modern tech stacks including React Native, React.js, Next.js, TypeScript, and various cloud services.', 'PART_TIME', '["eazydukan","webrasoi","zluper"]', '{"from":"blue","to":"indigo"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('physicswallah', 'PW (PhysicsWallah) Skills', 'Content Writer/Developer', '2023-05-01', '2024-01-01', 'Remote', 'Developed an in-depth React Native course tailored for students to learn React Native from the ground up, with a special focus on developing applications using Expo, ensuring comprehensive coverage of essential skills and concepts. Provided extensive guidance to students through a variety of detailed examples, hands-on exercises, and real-world projects, ensuring students gained a practical and thorough understanding of React Native development that enabled them to apply their knowledge effectively. Carefully structured the course content to cover all critical aspects of React Native, from initial setup and basic components to advanced features and optimization techniques, creating a robust curriculum designed to offer students a well-rounded and deep learning experience in React Native.', 'FREELANCE', '[]', '{"from":"red","to":"orange"}');
INSERT OR REPLACE INTO experiences (id, name, role, work_start, work_end, location, description, type, works, gradient) VALUES
  ('renovateai', 'Trial & Error Inc.', 'Software Engineer', '2025-09-01', NULL, 'Remote', 'Contributed to the development of RenovateAI, an AI-powered home design application that enables users to visualize and plan home renovations by transforming photos of their spaces into professionally styled interiors with virtual staging, wall paint previews, and furniture arrangement. Completely revamped key user-facing features including the onboarding flow, renovation experience, and home screen, resulting in increased user conversions. Implemented comprehensive accessibility (a11y) improvements across all features worked on, ensuring the app is usable and inclusive for all users. Improved the legacy codebase architecture and optimized performance throughout the app, significantly reducing technical debt and enhancing overall app responsiveness. Handled on-call responsibilities and resolved critical production bugs to ensure a seamless and frictionless user experience for homeowners planning their renovation projects.', 'FULL_TIME', '["renovate-ai","yardplan"]', '{"from":"pink","to":"orange"}');

DELETE FROM works WHERE id NOT IN ('eazydukan', 'webrasoi', 'zluper', 'konversi-fleet', 'konversi-pos', 'konversi-attendance', 'bvmrf', 'rhia', 'renovate-ai', 'privycode-mobile', 'yardplan');
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('eazydukan', 'EazyDukan', 'Multilingual retail management platform (mobile & web) with subscription tiers, multi-outlet management, full POS system, and AI-powered features. Web platform provides a large UI for managing inventory, adding transactions (POS), and quick commerce functionality.', 'Developed a multilingual retail management app (mobile & web) featuring subscription tiers, multi-outlet and staff management, a full POS system with real-time inventory tracking, and support for cash, QR code, and Razorpay SMS payments. Integrated AI capabilities to auto-scan restaurant menus into inventory, generate promotional materials, manage coupons, handle product returns, and offer a one-click "86" function, alongside detailed sales, revenue, and analytics reporting. Built online ordering with delivery coordination (in-house or third-party), WhatsApp-based customer feedback, and a Customer Display mode for scrolling in-store promotions. The web project is mainly the mobile app but easier to manage stuff like a large UI for managing inventory, adding transactions (POS), etc. The shop.eazydukan.com is a quick commerce platform that shows shops nearby, and users could buy from them. The "shop" is a wildcard subdomain and could be named to anything based on your eazydukan account, so you could advertise your shop as dominos.eazydukan.com and it would take the user to a page where the user could purchase anything from your shop online, and the store owner could have it delivered to them.', '', '', 'MULTI_PLATFORM', NULL, 'com.eazydukan', 0, 0, 'lovepack', '["React Native","React.js","Next.js","TypeScript","Redux","Zustand","WebSocket","Firebase","Razorpay","Thermal Printers","Bluetooth","Axios","GitLab","Tailwind"]', 0, '["https://images.sumit.codes/portfolio/works/eazydukan/mobile/01-home.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/02-pos-billing.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/03-transaction-logs.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/04-add-product.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/05-product-photo.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/06-menu-setup.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/07-menu-scan.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/08-delivery-radius.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/09-upi-qr.jpg","https://images.sumit.codes/portfolio/works/eazydukan/mobile/10-marketplaces.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/01-storefront.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/02-product.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/03-location.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/04-catalog.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/05-cart.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/06-coupons.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/07-order-status.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/08-order-history.jpg","https://images.sumit.codes/portfolio/works/eazydukan/web/09-order-details.jpg"]', '["https://www.eazydukan.com","https://shop.eazydukan.com/"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('webrasoi', 'WebRasoi', 'Restaurant-focused version of EazyDukan with enhanced functionality for restaurants, including AI-based menu creation, one-click "86" feature, and AI-generated images and descriptions for a polished experience.', 'WebRasoi is a restaurant-focused version of EazyDukan with way better functionality specifically designed for restaurants. It features AI-based inventory (menu) creation, one-click "86" feature for out-of-stock items, and AI-generated images and descriptions so it never felt bland. Similar to EazyDukan, when adding inventory, you could just take a picture of what the item is, and AI would fill all of the relevant details, ask you to confirm, and done. This streamlined the menu creation process and ensured consistent, professional-looking menu items with AI-generated content.', '', '', 'MOBILE', NULL, 'com.webrasoi', 0, 0, 'lovepack', '["React Native","TypeScript","Redux","Zustand","WebSocket","Firebase","Razorpay","Thermal Printers","Bluetooth","Axios","GitLab"]', 0, '["https://images.sumit.codes/portfolio/works/webrasoi/01-manage-menu.jpg","https://images.sumit.codes/portfolio/works/webrasoi/02-inventory-operations.jpg","https://images.sumit.codes/portfolio/works/webrasoi/03-category-details.jpg","https://images.sumit.codes/portfolio/works/webrasoi/04-outlet-management.jpg","https://images.sumit.codes/portfolio/works/webrasoi/05-online-store.jpg","https://images.sumit.codes/portfolio/works/webrasoi/06-orders.jpg","https://images.sumit.codes/portfolio/works/webrasoi/07-order-details.jpg","https://images.sumit.codes/portfolio/works/webrasoi/08-delivery-settings.jpg","https://images.sumit.codes/portfolio/works/webrasoi/09-coupons.jpg","https://images.sumit.codes/portfolio/works/webrasoi/10-configure-checkout.jpg","https://images.sumit.codes/portfolio/works/webrasoi/11-store-marketing.jpg","https://images.sumit.codes/portfolio/works/webrasoi/12-staff-management.jpg","https://images.sumit.codes/portfolio/works/webrasoi/13-card-payments.jpg","https://images.sumit.codes/portfolio/works/webrasoi/14-analytics.jpg","https://images.sumit.codes/portfolio/works/webrasoi/15-wallet-subscription.jpg","https://images.sumit.codes/portfolio/works/webrasoi/16-delivery-partners.jpg","https://images.sumit.codes/portfolio/works/webrasoi/17-storefront-promo.jpg","https://images.sumit.codes/portfolio/works/webrasoi/18-more.jpg"]', '["webrasoi.com"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('zluper', 'Zluper', 'Thrift fashion app where users can discover and purchase amazing thrift clothing from top brands. Features an Instagram Reels-like feed with HLS-optimized video streaming via expo-video and WebP-optimized images, wishlisting, rewards, referrals, wallet cashbacks, and a creator program for influencer events. Built an admin dashboard for easier management of inventory, data, orders, and more.', 'Zluper is a thrift fashion app where users can checkout amazing thrift clothing from top brands, buy them, share them, buy them for friends, get rewards, and participate in influencer events through Zluper''s creator program (sign up available on web). The mobile version is WAY better with an Instagram Reels-like feed on the homescreen that you can scroll through all day to checkout amazing fashion. It uses HLS with expo-video for videos to ensure network quality does not affect how fast/slow the media loads, only the quality, and WebP format with expo-image for optimized image loading. The app leverages Expo Application Services (EAS) for OTA updates and easier version releases on app stores. Key features include the performant Instagram Reels-like feed with support for both videos and images, wishlisting, buying, coupon codes, referrals, sharing, rewards, wallet cashbacks, referral earnings, and more. The web version is also available for purchasing, though the mobile experience is significantly enhanced. Additionally, I built a comprehensive admin dashboard that provides easier management of inventory, inventory data, orders, and other administrative tasks, streamlining the backend operations for the platform.', '', '', 'MULTI_PLATFORM', '6754866276', 'com.zluper', 0, 1, 'lovepack', '["Expo","React Native","React.js","Vite","Tailwind","NativeWind","React Query","Zustand","AWS","Google Cloud Console","EAS","Redux","Firebase","Sentry","TypeScript","PostHog","Razorpay SDK"]', 0, '["https://images.sumit.codes/portfolio/works/zluper/mobile/01-home.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/02-product-detail.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/03-co-ord-sets.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/04-categories.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/05-product.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/06-cart.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/07-cart-coupon.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/08-order-history.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/09-returns.jpg","https://images.sumit.codes/portfolio/works/zluper/mobile/10-profile.jpg","https://images.sumit.codes/portfolio/works/zluper/web/01-home.jpg","https://images.sumit.codes/portfolio/works/zluper/web/02-listing.jpg","https://images.sumit.codes/portfolio/works/zluper/web/03-product.jpg","https://images.sumit.codes/portfolio/works/zluper/web/04-filters.jpg","https://images.sumit.codes/portfolio/works/zluper/web/05-checkout.jpg","https://images.sumit.codes/portfolio/works/zluper/web/06-order-success.jpg","https://images.sumit.codes/portfolio/works/zluper/web/07-profile.jpg"]', '["zluper.com","web.zluper.com"]', NULL, NULL);
