  ('konversi-fleet', 'Konversi Fleet - Truck Fleet Management App', 'Truck fleet management app with job flow, job history, real-time location tracking for job assignments, image uploads, and technician maintenance workflows.', 'Developed a Fleet Management App job flow, job history and real-time location tracking for job assignments, image uploads, and technician maintenance workflows.', '', '', 'MOBILE', NULL, NULL, 1, 0, 'konversi', '["Expo","React Native","TypeScript","Axios","Redux","GitHub","CI/CD","SumoLogic"]', 0, '["https://images.sumit.codes/portfolio/works/konversi-fleet/01-weekly-checklist.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/02-replace-tires.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/03-vehicle-list.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/04-tire-diagram.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/05-urgent-maintenance.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/06-job-order-dropoff.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/07-job-order-map.jpg","https://images.sumit.codes/portfolio/works/konversi-fleet/08-inspection-history.jpg"]', NULL, NULL, NULL);
