  ('konversi-pos', 'Konversi POS - Full-fledged POS App', 'Full-fledged POS app for park operations with thermal printer support, transaction history, and report data printing. Handled 500-1000+ daily transactions seamlessly.', 'Built a POS App for park operations, integrating thermal printer support, transaction history, and report data printing. The app handled 500-1000+ transactions daily seamlessly with no hiccups.', '', '', 'MOBILE', NULL, NULL, 1, 0, 'konversi', '["Expo","React Native","TypeScript","Axios","Redux","GitHub","CI/CD","SumoLogic","Bluetooth","Thermal Printers"]', 0, '["https://images.sumit.codes/portfolio/works/konversi-pos/01-home.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/02-order-summary.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/03-payment-method.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/04-print-ticket.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/05-reports.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/06-history.jpg","https://images.sumit.codes/portfolio/works/konversi-pos/07-closing-report.jpg"]', NULL, NULL, NULL);
