  ('konversi-attendance', 'KWork - Attendance Tracking/Logging App', 'Attendance tracking app using Expo geolocation and camera-based photo verification for secure clock-in/out, leave management, and daily work hour tracking.', 'Created an Attendance Logging App using Expo''s geolocation services and camera-based photo verification to enforce secure clock-in/out, manage leave requests, and track daily work hours.', '', '', 'MOBILE', NULL, NULL, 1, 0, 'konversi', '["Expo","React Native","TypeScript","GitHub","CI/CD","Axios","SumoLogic","Redux"]', 0, '["https://images.sumit.codes/portfolio/works/konversi-attendance/01-login.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/02-clock-in.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/03-apply-leave.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/04-leave-range.jpg","https://images.sumit.codes/portfolio/works/konversi-attendance/05-leave-requests.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('bvmrf', 'BVMRF - Vet Health', 'Comprehensive mobile app designed to support Veterans in their health and well-being journey, offering educational resources, personalized content on therapeutic areas, VA facility directory, and information on eligibility and benefits.', 'BVMRF Vet-Health is a comprehensive mobile application designed to support Veterans in their health and well-being journey. It offers a wealth of educational resources, personalized content on specific therapeutic areas, and valuable information on VA-related topics and services. Users can access a vast library of educational content tailored to their specific needs, stay informed about relevant therapeutic areas, and learn about the latest treatments and therapies available for Veterans. The app also provides a comprehensive directory of VA facilities and services, guidance on eligibility and benefits, and updates on VA-related news. Additionally, it keeps users informed about advancements in medical research and clinical trials, offering opportunities to participate in studies that may benefit them and contribute to the advancement of Veterans healthcare. The app is developed by the Bronx Veterans Medical Research Foundation (BVMRF), a nonprofit organization dedicated to advancing research and education activities to enhance the quality of care and health for Veterans.', '', '', 'MOBILE', '6476032857', 'my.bvmrf.app', 0, 1, 'ariveguru', '["React Native","Bitbucket","JavaScript","Redux","Redux Saga"]', 0, '["https://images.sumit.codes/portfolio/works/bvmrf/01-splash.jpg","https://images.sumit.codes/portfolio/works/bvmrf/02-login.jpg","https://images.sumit.codes/portfolio/works/bvmrf/03-home.jpg","https://images.sumit.codes/portfolio/works/bvmrf/04-quick-menu.jpg","https://images.sumit.codes/portfolio/works/bvmrf/05-badges.jpg","https://images.sumit.codes/portfolio/works/bvmrf/06-badge-detail.jpg","https://images.sumit.codes/portfolio/works/bvmrf/07-surveys.jpg","https://images.sumit.codes/portfolio/works/bvmrf/08-trials.jpg","https://images.sumit.codes/portfolio/works/bvmrf/09-resources.jpg","https://images.sumit.codes/portfolio/works/bvmrf/10-articles.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('rhia', 'RHIA - Life-like AI Assistant', 'Life-like AI assistant for user registration, appointment scheduling, and task management, deployable across multiple office locations to streamline operations and improve productivity.', 'Built RHIA, an AI assistant for tasks like user registration, appointment scheduling, and task management, deployable across multiple office locations. Leveraged AI technologies efficiently to streamline office operations and improve productivity. This was a POC project, supposed to be demo''d at the Bengaluru Tech Summit. You would literally talk to a person (AI) on screen, regarding whatever you wanted to talk about (obviously it being relevant to who RHIA would be working for OR what data was fed into RHIA).', '', '', 'WEB', NULL, NULL, 0, 0, 'ariveguru', '["React","Vite","Tailwind","HeyGen","AI/ML","OpenAI","Gemini","Zustand","Axios","JavaScript","Bitbucket","WebSocket"]', 0, '[]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('renovate-ai', 'Renovate AI', 'AI-powered home design and renovation app with virtual staging, 3D elevations, image upscaling, and over 100 curated styles. Revamped onboarding and home screen, significantly improving user conversions and app performance.', 'Worked on various projects/part of the Renovate AI mobile app, such as completely revamping the onboarding, renovation experience, home screen, and more, increasing user conversions. Worked on improving legacy codebase and increased performance throughout the app, removing a huge chunk of technical debt. Handled on-call as well as critical bugs in production, ensuring end users have a frictionless app experience. Renovate AI is a cutting-edge application that revolutionizes home design and renovation processes using advanced AI. It features virtual staging, 3D elevations, image upscaling to 4K, exterior renovation, landscaping design with over 40 styles, sketch-to-render capabilities, wall makeovers, exterior painting, and object removal. The app is powered by over 10 AI models and offers more than 100 curated styles for interior and exterior design.', '', '', 'MOBILE', '1661709494', 'app.renovateai', 0, 1, 'renovateai', '["React Native","TypeScript","Redux","Axios","React Query","Redux Saga","GitHub","CI/CD","Expo","Expo UI","Firebase","RevenueCat","Sentry","PostHog"]', 0, '["https://images.sumit.codes/portfolio/works/renovate-ai/01-remodel-with-ai.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/02-any-style.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/03-kitchen-and-bath.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/04-type-what-you-want.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/05-floors-counters.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/06-wall-colors-live.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/07-paint-instantly.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/08-materials.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/09-living-room-render.jpg","https://images.sumit.codes/portfolio/works/renovate-ai/10-cost-estimate.jpg"]', NULL, NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('privycode-mobile', 'PrivyCode - Safe Code Sharing', 'Mobile app for creating secure, time-limited, view-only access links to private GitHub repositories. Perfect for developers sharing code with recruiters, clients, or collaborators without compromising security.', 'PrivyCode revolutionizes how developers share their code by creating secure, time-limited, view-only access links to private GitHub repositories. No more making your code public or managing complex permissions. Key features include secure by design (code stays private, only shared content is accessible), time-limited access with expiration dates, view-only access (recipients can view but cannot clone, download, or modify), usage analytics to track who viewed code and when, instant sharing to generate secure links in seconds, and mobile-first design to manage shared links on the go. Perfect for developers sharing code with recruiters, freelancers showing work to potential clients, teams collaborating with external reviewers, and open source maintainers sharing private projects.', '', '', 'MOBILE', NULL, 'com.samtastic.privycodemobile', 0, 1, NULL, '["Expo","React Native","Reanimated","GitHub","EAS","Firebase"]', 0, '["https://images.sumit.codes/portfolio/works/privycode-mobile/01-welcome.jpg","https://images.sumit.codes/portfolio/works/privycode-mobile/02-generate-link.jpg","https://images.sumit.codes/portfolio/works/privycode-mobile/03-analytics.jpg"]', '["https://privycode.com"]', NULL, NULL);
INSERT OR REPLACE INTO works (id, name, description_short, description_long, icon, category, type, app_store_id, play_store_id, is_internal, featured, company_id, technologies, rating, screenshots, web_urls, source_code, google_group_url) VALUES
  ('yardplan', 'YardPlan', 'AI landscaping app: photograph your yard, get Gemini-rendered redesigns you can iterate on, then a buildable plan with plants suited to your region. Built end to end: the Expo SDK 56 / React Native new-architecture app and its Cloudflare Workers backend (Hono, D1, R2, Queues).', 'YardPlan lets homeowners photograph their yard and see it redesigned by AI. Each render can branch from the original photo or from an earlier render, so users explore variations without losing their place, and a finished design turns into a buildable plan with region-appropriate plants. Built the product end to end. The mobile app runs on Expo SDK 56 and React Native 0.85 (new architecture only) with React 19 and the React Compiler, expo-router file-based routing, and a strict layered architecture (utils, services, api, hooks, providers, screens) enforced by repo rules. It ships Firebase auth (Google, Apple, Facebook, passwordless email), RevenueCat subscriptions and paywalls, iOS widgets, share-intent and Branch deep links, push notifications, an offline mode, Lingui i18n, and PostHog analytics with a generated event catalog, styled through semantic theme tokens via uniwind. The backend is a Firebase-authenticated Cloudflare Worker on Hono with D1 for data, R2 for photos and renders, and Cloudflare Queues driving the Gemini render and plan pipelines asynchronously, so a render survives the app closing. Both sides use Drizzle, Biome/ultracite, tests and husky to keep the codebase consistent.', '', '', 'MOBILE', '6784333021', 'app.yardplan', 0, 1, 'renovateai', '["Expo","React Native","React 19","React Compiler","TypeScript","expo-router","uniwind","Tailwind","React Query","Redux Toolkit","Firebase","RevenueCat","PostHog","Branch","Lingui","Reanimated","Skia","MMKV","EAS","Cloudflare Workers","Hono","D1","R2","Cloudflare Queues","Drizzle","Gemini","Biome","Jest"]', 0, '["https://images.sumit.codes/portfolio/works/yardplan/01-reimagine-your-yard.jpg","https://images.sumit.codes/portfolio/works/yardplan/02-priced-plan.jpg","https://images.sumit.codes/portfolio/works/yardplan/03-describe-your-dream.jpg","https://images.sumit.codes/portfolio/works/yardplan/04-know-what-grows.jpg","https://images.sumit.codes/portfolio/works/yardplan/05-redesigned-yard.jpg","https://images.sumit.codes/portfolio/works/yardplan/06-build-this-weekend.jpg"]', '["yardplan.app"]', NULL, NULL);

